async function load(){const[{data:md},{data:td},{data:hd}]=await Promise.all([sb.from('members').select('*').order('name'),sb.from('tasks').select('*').order('logged_at',{ascending:false}),sb.from('task_history').select('*').order('changed_at',{ascending:false})]);members=md||[];tasks=td||[];hist=hd||[];render();}
function mt(id){return tasks.filter(t=>t.member_id===id);}
function mst(id){const mine=mt(id);const tot=mine.length,don=mine.filter(t=>t.status==='done').length,lat=mine.filter(t=>t.status==='late').length,rt=tot?Math.round(don/tot*100):0;const wt=mine.filter(t=>t.actual_minutes&&t.eta_minutes);const aA=wt.length?Math.round(wt.reduce((s,t)=>s+t.actual_minutes,0)/wt.length):null,aE=wt.length?Math.round(wt.reduce((s,t)=>s+t.eta_minutes,0)/wt.length):null;return{total:tot,done:don,late:lat,rate:rt,avgA:aA,avgE:aE,noR:mine.filter(t=>t.result_category==='No result').length,nf:mine.filter(t=>t.result_category==='Needs review'||(t.notes||'').toLowerCase().includes('follow')).length};}
function vrd(id){const s=mst(id);if(!s.total)return{label:'No data',cls:'nodata'};if(s.late>=2)return{label:'Falling behind',cls:'behind'};if(s.rate>=80)return{label:'Producing',cls:'producing'};if(s.rate>=50)return{label:'Watch',cls:'watch'};return{label:'Falling behind',cls:'behind'};}
function stag(s){const m={done:['Done','done'],prog:['In progress','prog'],late:['Late','late'],pending:['Pending','pending']};const[l,c]=m[s]||['?','pending'];return'<span class="tag '+c+'">'+l+'</span>';}
function ebar(eta,act){if(!eta)return'';const pct=act?Math.min(Math.round(act/eta*100),150):0;const over=act>eta,cls=!act?'b':over?'r':'g';return'<div style="margin-top:4px"><div class="erow"><span>ETA '+fm(eta)+(act?' · '+fm(act):'')+'</span><span>'+(act?(over?'+'+fm(act-eta)+' over':'-'+fm(eta-act)+' under'):'—')+'</span></div><div class="btrack"><div class="bfill '+cls+'" style="width:'+Math.min(pct,100)+'%"></div></div></div>';}
function getTH(tid){return hist.filter(h=>h.task_id===tid);}
function renderH(tid){const h=getTH(tid);if(!h.length)return'<div style="color:var(--text3);font-size:11px">No changes.</div>';return h.map(x=>{const c=members.find(m=>m.id===x.changed_by);return'<div class="hist-item"><div class="hdot"></div><div><div class="htxt"><strong>'+(c?.name||'?')+'</strong> changed <strong>'+x.field_changed+'</strong>: "'+x.old_value+'"→"'+x.new_value+'"</div><div class="htime">'+new Date(x.changed_at).toLocaleString()+'</div></div></div>';}).join('');}
function genIns(){const ins=[];const tod=new Date().toDateString();const todT=tasks.filter(t=>new Date(t.logged_at).toDateString()===tod);members.forEach(m=>{if(!todT.some(t=>t.member_id===m.id))ins.push({t:'warn',i:'⚠️',txt:'<strong>'+m.name+'</strong> has logged 0 tasks today.'});});members.forEach(m=>{const mine=mt(m.id).filter(t=>t.actual_minutes&&t.eta_minutes);if(mine.length<2)return;const ae=mine.reduce((s,t)=>s+t.eta_minutes,0)/mine.length,aa=mine.reduce((s,t)=>s+t.actual_minutes,0)/mine.length,d=Math.round(aa-ae);if(d>20)ins.push({t:'warn',i:'🕐',txt:'<strong>'+m.name+'</strong> averages <strong>+'+fm(d)+'</strong> over ETA.'});if(d<-15)ins.push({t:'good',i:'⚡',txt:'<strong>'+m.name+'</strong> is <strong>'+fm(Math.abs(d))+' under ETA</strong>.'});});members.forEach(m=>{const s=mst(m.id);if(s.late>=3)ins.push({t:'bad',i:'🚨',txt:'<strong>'+m.name+'</strong> has <strong>'+s.late+' late tasks</strong>.'});else if(s.late>=1)ins.push({t:'warn',i:'⚠️',txt:'<strong>'+m.name+'</strong> has <strong>'+s.late+' late task'+(s.late>1?'s':'')+'</strong>.'});});const ed=tasks.filter(t=>t.edited_at);if(ed.length)ins.push({t:'info',i:'✏️',txt:'<strong>'+ed.length+' task'+(ed.length>1?'s have':' has')+'</strong> been edited after logging.'});const ttR={};tasks.forEach(t=>{if(t.task_type&&t.result_category&&t.result_category!=='No result')ttR[t.task_type]=(ttR[t.task_type]||0)+1;});const best=Object.entries(ttR).sort((a,b)=>b[1]-a[1])[0];if(best)ins.push({t:'good',i:'🏆',txt:'"<strong>'+best[0]+'</strong>" is top task — <strong>'+best[1]+' results</strong>.'});const tot=tasks.length,don=tasks.filter(t=>t.status==='done').length,rt=tot?Math.round(don/tot*100):0;if(tot>0){if(rt>=80)ins.push({t:'good',i:'✅',txt:'Completion rate is <strong>'+rt+'%</strong>.'});else if(rt>=50)ins.push({t:'warn',i:'📊',txt:'Completion rate is <strong>'+rt+'%</strong> — room to improve.'});else ins.push({t:'bad',i:'🔴',txt:'Only <strong>'+rt+'%</strong> completion.'});}const tp=members.map(m=>({m,s:mst(m.id)})).filter(x=>x.s.total>0).sort((a,b)=>b.s.rate-a.s.rate)[0];if(tp&&tp.s.rate>0)ins.push({t:'good',i:'⭐',txt:'<strong>'+tp.m.name+'</strong> is top performer at <strong>'+tp.s.rate+'%</strong>.'});document.getElementById('ilist').innerHTML=ins.length?ins.map(x=>'<div class="ii '+x.t+'"><div style="font-size:13px;flex-shrink:0;margin-top:1px">'+x.i+'</div><div>'+x.txt+'</div></div>').join(''):'<div style="color:var(--text3);font-size:12px;padding:4px 0">Log tasks to generate insights.</div>';}
