function openEditSelf(){openEM(cu.id);}
function openET(tid){const t=tasks.find(x=>x.id===tid);if(!t)return;document.getElementById('tmtitle').textContent='Edit task';document.getElementById('tsave').textContent='Update task';document.getElementById('teid').value=tid;sMid=t.member_id;sRoles=t.role_area?[t.role_area]:[];sTT=t.task_type||null;sRCs=t.result_category?t.result_category.split(',').map(s=>s.trim()).filter(Boolean):[];sEta=t.eta_minutes||null;sAct=t.actual_minutes||null;isRec=t.is_recurring||false;recFreq=t.recur_frequency||null;document.getElementById('tname').value=t.name||'';document.getElementById('tnotes').value=t.notes||'';document.getElementById('tstat').value=t.status||'done';document.getElementById('rtog').classList.toggle('on',isRec);document.getElementById('recwrap').style.display=isRec?'block':'none';['brad','bttad','brcad'].forEach(id=>document.getElementById(id).classList.remove('show'));bMembers();bRoles();bTTs();bRCs();bTimeG('etag','eta');bTimeG('actg','act');if(sEta){const b=Array.from(document.querySelectorAll('#etag .tbtn')).find(b=>TIMES.find(x=>x.m===sEta&&x.l===b.textContent));if(b)b.classList.add('on');}if(sAct){const b=Array.from(document.querySelectorAll('#actg .tbtn')).find(b=>TIMES.find(x=>x.m===sAct&&x.l===b.textContent));if(b)b.classList.add('on');}if(recFreq)document.querySelectorAll('.rbtn').forEach(b=>{if(b.textContent===recFreq)b.classList.add('on');});document.getElementById('TM').classList.add('open');}
function closeTM(){document.getElementById('TM').classList.remove('open');closeDrill();}
async function saveT(){const eid=document.getElementById('teid').value;if(!sMid){toast('Select a member','error');return;}if(!sTT){toast('Select a task type','error');return;}const name=document.getElementById('tname').value.trim(),status=document.getElementById('tstat').value,notes=document.getElementById('tnotes').value.trim(),resultStr=sRCs.join(', ');const payload={member_id:sMid,name:name||sTT,status,role_area:sRoles[0]||null,task_type:sTT,result_category:resultStr||null,notes,eta_minutes:sEta||null,actual_minutes:sAct||null,is_recurring:isRec,recur_frequency:recFreq||null};if(eid){const orig=tasks.find(t=>t.id===eid);if(orig){const fields=['status','role_area','task_type','result_category','eta_minutes','actual_minutes','notes'];for(const f of fields){if(String(orig[f]||'')!==String(payload[f]||''))await sb.from('task_history').insert([{task_id:eid,changed_by:cu.id,field_changed:f,old_value:String(orig[f]||''),new_value:String(payload[f]||'')}]);}}payload.edited_at=new Date().toISOString();payload.edited_by=cu.id;const{error}=await sb.from('tasks').update(payload).eq('id',eid);if(error){toast('Error updating','error');return;}toast('Task updated ✓');}else{const{error}=await sb.from('tasks').insert([payload]);if(error){toast('Error saving','error');return;}toast('Task logged ✓');}closeTM();await load();}
function delT(tid,btn){if(btn.textContent==='Del'||btn.textContent==='Delete'){btn.textContent='Sure?';setTimeout(()=>{if(btn.textContent==='Sure?')btn.textContent=btn.dataset.orig||'Del';},3000);return;}(async()=>{await sb.from('tasks').delete().eq('id',tid);closeDrill();document.getElementById('dd').classList.remove('open');toast('Task deleted');await load();})();}
function openM(){document.getElementById('mmtitle').textContent='Add team member';document.getElementById('meid').value='';document.getElementById('mdel').style.display='none';['mname','mrole','mtags','mdesc','mpin'].forEach(id=>document.getElementById(id).value='');document.getElementById('madmin').value='false';document.getElementById('mcolor').value='teal';document.getElementById('MM').classList.add('open');}
function openEM(mid){const m=members.find(x=>x.id===mid);if(!m)return;document.getElementById('mmtitle').textContent='Edit member';document.getElementById('meid').value=mid;document.getElementById('mdel').style.display='flex';document.getElementById('mname').value=m.name||'';document.getElementById('mrole').value=m.role||'';document.getElementById('mtags').value=m.role_tags||'';document.getElementById('mdesc').value=m.description||'';document.getElementById('mpin').value=m.pin||'';document.getElementById('madmin').value=m.is_admin?'true':'false';document.getElementById('mcolor').value=m.color||'teal';document.getElementById('MM').classList.add('open');}
function closeMM(){document.getElementById('MM').classList.remove('open');}
async function saveM(){const eid=document.getElementById('meid').value,name=document.getElementById('mname').value.trim(),role=document.getElementById('mrole').value.trim(),description=document.getElementById('mdesc').value.trim(),color=document.getElementById('mcolor').value,role_tags=document.getElementById('mtags').value.trim(),pin=document.getElementById('mpin').value.trim(),is_admin=document.getElementById('madmin').value==='true';if(!name||!role){toast('Name and role required','error');return;}const payload={name,role,description,color,role_tags,pin,is_admin};let error;if(eid){({error}=await sb.from('members').update(payload).eq('id',eid));}else{({error}=await sb.from('members').insert([payload]));}if(error){toast('Error saving','error');return;}closeMM();toast(eid?name+' updated ✓':name+' added ✓');if(eid&&cu?.id===eid){cu.color=color;const c=COLORS[color]||COLORS.teal;document.getElementById('uav').style.background=c.bg;document.getElementById('uav').style.color=c.text;}await load();}
function delM(){const eid=document.getElementById('meid').value;if(!eid)return;const btn=document.getElementById('mdel');if(btn.textContent==='Delete'){btn.textContent='Confirm?';setTimeout(()=>{if(btn.textContent==='Confirm?')btn.textContent='Delete';},3000);return;}(async()=>{await sb.from('tasks').delete().eq('member_id',eid);const{error}=await sb.from('members').delete().eq('id',eid);if(error){toast('Error','error');return;}closeMM();toast('Member deleted');await load();})();}
function gp(page,btn){document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));document.querySelectorAll('.ni').forEach(b=>b.classList.remove('active'));document.getElementById('page-'+page).classList.add('active');if(btn)btn.classList.add('active');if(page==='calendar')renderCal();if(page==='performance')rCharts();if(page==='oversight')rOversight();if(page==='intelligence')rIntel();if(page==='library')rLib();if(page==='roles')rRoles();}
function toast(msg,type='success'){const t=document.getElementById('toast');t.textContent=msg;t.className='toast '+type+' show';setTimeout(()=>t.className='toast',2600);}
['TM','MM','ECM','CPM'].forEach(id=>{document.getElementById(id).addEventListener('click',e=>{if(e.target===document.getElementById(id))document.getElementById(id).classList.remove('open');});});
document.getElementById('DD').addEventListener('click',e=>{if(e.target===document.getElementById('DD'))closeDrill();});
sb.channel('kpi').on('postgres_changes',{event:'*',schema:'public',table:'tasks'},()=>load()).on('postgres_changes',{event:'*',schema:'public',table:'members'},()=>load()).on('postgres_changes',{event:'*',schema:'public',table:'task_history'},()=>load()).subscribe();
initLogin();
